import{z as l,x as n,o as t,c as d,q as r,j as i,D as e,d as A,s as o,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"系统性对随机缺陷","description":"","frontmatter":{"title":"系统性对随机缺陷","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/systematic-vs-random-defects.md","filePath":"litho/systematic-vs-random-defects.md","lastUpdated":1791063341000}'),p={name:"litho/systematic-vs-random-defects.md"};function m(D,a,C,h,c,F){const s=n("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="系统性对随机缺陷" tabindex="-1">系统性对随机缺陷 <a class="header-anchor" href="#系统性对随机缺陷" aria-label="Permalink to &quot;系统性对随机缺陷&quot;">​</a></h1><div class="epigraph"><p>系统缺陷在每颗管芯同一拓扑重复，改 OPC 或规则能一次杀掉；随机缺陷按位置抽签，洁净与光子统计才是杠杆。</p><footer>—— 对照良率工程对 systematic vs random 的划分；计算光刻热点与颗粒缺陷的分工</footer></div><p><a href="/litho/critical-area">上一课</a>把随机颗粒写成 \\(A_\\mathrm{cr}\\)。缺口是分类：探针图上的重复失败是系统，散点是随机，混在一张 \\(D\\) 里会开错药。<a href="/litho/hotspot-pv">热点 PV</a> 已定义过程变化下的系统杀手；本课钉良率账的拆分。EUV 光子与化学随机，留给<a href="/litho/stochastic-yield">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>系统：错色、OPC 不足、切线偏置、焦距地图、掩模缺陷打印。特征是空间重复或与布局相关。随机：颗粒、残留、部分光子缺孔。诊断：把失败管芯叠到设计上，看是否对齐同一 clips；与过程角相关则更像窗口问题。</p><p><span class="marginnote">直觉类比：系统缺陷像印书时制版错了一个字——每一本同一页同一位置都错，改一次版全修好；随机缺陷像装订时随机溅上的墨点——每本位置都不一样，只能靠保持车间干净来降低墨点密度。药方完全不同，所以先分类再动手。</span></p><p>缺口是<strong>两本账</strong>，不是再跑 LRC。系统用设计/OPC/PWQ 消灭，随机用洁净、过滤、剂量（对光子）和关键面积。APC 补均值 CD 可能改善系统窗口，对颗粒几乎无用。</p><h3 id="掩模缺陷是系统的一种" tabindex="-1">掩模缺陷是系统的一种 <a class="header-anchor" href="#掩模缺陷是系统的一种" aria-label="Permalink to &quot;掩模缺陷是系统的一种&quot;">​</a></h3><p>掩模上的固定缺陷在每场同一位置打印，像系统。AIMS 与掩模检测课已有；良率上应按「每场重复」识别，不要当晶圆颗粒去改轨道。</p><p><span class="marginnote">边缘环失败看起来「随机」，其实是边缘场系统。叠图要对晶圆坐标，也要对场坐标。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>叠图：管芯失败 × 设计 clips × 场坐标 × 晶圆半径。Pareto：系统 clips 清单 vs 随机密度。动作：系统走 LFD/OPC/食谱；随机走洁净与检测。与分派：系统批可能整批同源（错版），重工有效；随机按 \\(D\\) 抽检。</p><p>场坐标叠图能抓住掩模打印缺陷和扫描机指纹；设计叠图抓住 OPC 热点。两张图都要做。良率工程对 systematic vs random 的划分，操作上就是这两张叠图。</p>',13)),(t(),i(B,null,{default:e(()=>[o(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%89%80%E6%9C%89%E5%A4%B1%E8%B4%A5%E7%AE%A1%E8%8A%AF%E5%9D%90%E6%A0%87%22%5D%20--%3E%20B%5B%22%E8%AE%BE%E8%AE%A1%E5%8F%A0%E5%9B%BE%EF%BC%9A%E5%AF%B9%E9%BD%90%E5%90%8C%E4%B8%80%E7%89%88%E5%9B%BE%20clips%22%5D%0A%20%20A%20--%3E%20C%5B%22%E5%9C%BA%E5%8F%A0%E5%9B%BE%EF%BC%9A%E5%AF%B9%E9%BD%90%E5%9C%BA%E5%86%85%E5%90%8C%E4%B8%80%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20B%20--%3E%20D%5B%22%E6%8A%93%20OPC%20%E7%83%AD%E7%82%B9%20%2F%20%E9%94%99%E8%89%B2%20%2F%20%E7%84%A6%E8%B7%9D%E5%9C%B0%E5%9B%BE%22%5D%0A%20%20C%20--%3E%20E%5B%22%E6%8A%93%E6%8E%A9%E6%A8%A1%E7%BC%BA%E9%99%B7%20%2F%20%E6%89%AB%E6%8F%8F%E6%9C%BA%E6%8C%87%E7%BA%B9%20%2F%20%E8%BE%B9%E7%BC%98%E5%9C%BA%22%5D%0A%20%20D%20--%3E%20F%5B%22%E4%BF%AE%E8%AE%BE%E8%AE%A1%EF%BC%9AOPC%20%E4%B8%8E%E8%A7%84%E5%88%99%22%5D%0A%20%20E%20--%3E%20G%5B%22%E4%BF%AE%E7%A1%AC%E4%BB%B6%EF%BC%9A%E6%8E%A9%E6%A8%A1%E9%87%8D%E5%B7%A5%20%2F%20%E6%9C%BA%E5%8F%B0%E6%A0%A1%E6%AD%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[A("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"系统失效概率对管芯近似 0 或 1（在窗口外则全死）。随机是 \\(1-e^{-DA}\\)。混合良率 \\(\\approx Y_\\mathrm{sys} \\times Y_\\mathrm{rand}\\)。把系统残差塞进 \\(D\\)，会高估洁净收益。过程变化把「临界系统」变成批间闪烁，看起来像随机，要用 PWQ 与过程角去验。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"数字实例：随机公式 \\(Y=e^{-DA}\\)，若颗粒密度 \\(D=0.1\\) 个/mm\\(^2\\)、关键面积 \\(A=10\\) mm\\(^2\\)，则 \\(DA=1\\)，随机良率只有 \\(e^{-1}\\approx37\\%\\)。把 \\(D\\) 压到 0.01，同样的 \\(A\\) 良率就回升到约 91%——洁净度的杠杆有多大，一算便知。")],-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"常见误区：初学者容易把「随机热点」当成分类失败。实际上两者可以相乘：NILS 太低的地方（系统弱点）对一颗恰好落在附近的颗粒（随机事件）更敏感。分类答的是「先修哪本账」，不是「两者互斥」。")],-1)),(t(),i(B,null,{default:e(()=>[o(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E6%8E%A2%E9%92%88%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20STACK%5B%22%E5%8F%A0%E8%AE%BE%E8%AE%A1%20%2F%20%E5%9C%BA%20%2F%20%E5%8D%8A%E5%BE%84%22%5D%0A%20%20STACK%20--%3E%20SYS%5B%22%E9%87%8D%E5%A4%8D%E6%8B%93%E6%89%91%20%E2%86%92%20%E7%B3%BB%E7%BB%9F%E8%B4%A6%22%5D%0A%20%20STACK%20--%3E%20RND%5B%22%E7%A9%BA%E9%97%B4%E6%95%A3%E7%82%B9%20%E2%86%92%20%E9%9A%8F%E6%9C%BA%E8%B4%A6%22%5D%0A%20%20SYS%20--%3E%20OPC%5B%22OPC%20%2F%20%E8%A7%84%E5%88%99%20%2F%20%E9%A3%9F%E8%B0%B1%22%5D%0A%20%20RND%20--%3E%20CA%5B%22%E5%85%B3%E9%94%AE%E9%9D%A2%E7%A7%AF%20%C3%97%20%E6%B4%81%E5%87%80%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p>设计叠图抓 OPC，场坐标叠图抓掩模与扫描机指纹。两张图分开，药才不会开错房间。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>分类有灰色：随机热点（NILS 低处更容易颗粒桥）。仍应先修 NILS。不把本课写成检测设备手册（后课）。</p><p>后课默认：良率 Pareto 分系统与随机。下一课专门把光子/化学随机从颗粒随机里再拆一刀。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>系统对齐设计与场；随机按位置抽签。</li><li>两本账，两种杠杆；禁止用 \\(D\\) 吞热点。</li><li>掩模打印缺陷按场重复识别。</li><li>出处：良率工程 systematic/random 划分；计算光刻热点传统。</li></ul>',6))])}const u=l(p,[["render",m]]);export{P as __pageData,u as default};
